def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    def opp_run_end():
        k = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'D':
                k += 1
            else:
                break
        return k

    def my_run_end():
        k = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'D':
                k += 1
            else:
                break
        return k

    def coop_run_end():
        k = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'C':
                k += 1
            else:
                break
        return k

    # Handle the first few rounds reassuringly so a short initial opponent
    # defect burst (TFT-style) does not cascade into a DD lock.
    if n == 1:
        return 'C'
    if n <= 4:
        if opp_run_end() >= 1:
            # Opponent defected recently; allow them one more chance before
            # settling, since the parent's measurements show a TFT partner
            # opens with 1-4 D's.  Trade short-term loss for recovery.
            if opp_run_end() >= 3:
                return 'D'
            return 'C'
        return 'C'

    opp_def = sum(1 for a in opp if a == 'D')
    coop_ratio = 1.0 - (opp_def / float(n))

    recent_len = 10 if n >= 10 else n
    recent = opp[-recent_len:]
    recent_def = recent_len - sum(1 for a in recent if a == 'C')
    recent_ratio = 1.0 - (recent_def / float(recent_len))
    k = opp_run_end()

    # Pure always-defect detection over a long window.
    if n >= 8:
        last8 = opp[-8:]
        d8 = sum(1 for a in last8 if a == 'D')
        if d8 >= 8:
            return 'D'
        if d8 <= 0:
            # Long clean cooperation: stay cooperative.
            return 'C'

    # Very hostile opponent: only defect, with rare probing C.
    if opp_def >= n - 2 and n >= 8:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Sustained defection: respond in kind, but occasionally re-test.
    if k >= 4:
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Opponent just defected.
    if opp[-1] == 'D':
        if k >= 3:
            return 'D'
        if k == 2:
            # Two in a row.  If recent record is clearly cooperative,
            # forgive once; otherwise retaliate once.
            if recent_ratio >= 0.75:
                return 'C'
            return 'D'
        # Single defection: mirror with one D unless recent record is strong.
        if coop_ratio >= 0.9 and recent_ratio >= 0.85:
            return 'C'
        return 'D'

    # Opponent cooperated last.  Decide whether to reciprocate or probe.
    if me[-1] == 'D':
        # We were retaliating; return to C to rebuild -- this is essential for
        # TFT and ALLC recovery.
        return 'C'

    # Cooperation streak.  Occasionally probe but never exploit heavily,
    # since defection noise on a TFT opponent collapses both scores.
    if n >= 6 and coop_ratio >= 0.85:
        if n % 19 == 0 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Mixed opponent: friendly tit-for-tat with mild forgiveness.
    if recent_ratio >= 0.6:
        return 'C'
    if recent_ratio <= 0.25:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Last-round considerations: with very few rounds left, tiny temptation
    # to defect exists, but the risk of losing long-run trust dominates, so
    # still cooperate when the opponent has been decent.
    remaining = 100 - n
    if remaining <= 2:
        if coop_ratio >= 0.5:
            return 'C'
        return 'D'

    if rng.random() < 0.05:
        return 'D'
    return 'C'
